<?php
declare(strict_types=1);require __DIR__.'/app/request-supply.php';$user=require_verified();$id=marketplace_text($_GET,'id',36,true);$offer=supply_offer($user,$id);if($offer['requester_organization_id']===$user['owner_id']&&$offer['status']==='SUBMITTED'){db()->prepare("UPDATE supply_offers SET status='VIEWED',viewed_at=UTC_TIMESTAMP() WHERE id=?")->execute([$id]);$offer['status']='VIEWED';request_event($offer['request_id'],$user,'OFFER_VIEWED',['supply_offer_id'=>$id]);}$terms=json_decode($offer['commercial_terms'],true)?:[];$technical=json_decode($offer['technical_response'],true)?:[];$deviations=json_decode($offer['deviations'],true)?:[];$versions=rows('SELECT * FROM supply_offer_versions WHERE supply_offer_id=? ORDER BY version_number DESC',[$id]);$messages=rows('SELECT m.*,u.full_name,o.name organization_name FROM request_messages m JOIN users u ON u.id=m.sender_user_id JOIN owners o ON o.id=u.owner_id WHERE m.supply_offer_id=? ORDER BY m.created_at',[$id]);$documents=rows('SELECT d.*,v.version_number FROM supply_offer_documents d JOIN supply_offer_versions v ON v.id=d.supply_offer_version_id WHERE v.supply_offer_id=? ORDER BY d.created_at',[$id]);$active='marketplace';$pageTitle='Supply Offer';require __DIR__.'/includes/operations-header.php';?>
<nav class="lease-tabs"><a href="requests">My Requests</a><a href="requests?view=offers">My Supply Offers</a><a href="marketplace-requests">Browse Requests</a></nav><header class="request-workspace-head"><div><p class="market-kicker">SUPPLY OFFER · VERSION <?= (int)$offer['current_version'] ?></p><h1><?= e($offer['request_title']) ?></h1><p><?= e($offer['supplier_name'].' → '.$offer['requester_name']) ?></p></div><span class="request-badge"><?= e($offer['status']) ?></span></header><section class="transaction-grid"><article><span>Equipment</span><strong><?= e($offer['equipment_name']) ?></strong></article><article><span>Quantity</span><strong><?= (int)$offer['quantity_offered'] ?></strong></article><article><span>Price / rate</span><strong><?= e(($terms['currency']??'').' '.number_format((float)($terms['amount']??0),2)) ?></strong></article><article><span>Basis</span><strong><?= e($terms['pricing_basis']??'—') ?></strong></article></section><section class="transaction-panel"><h2>Commercial response</h2><dl><?php foreach(['available_from'=>'Available from','available_until'=>'Available until','mobilization_delivery'=>'Mobilization / delivery','demobilization'=>'Demobilization','security_deposit'=>'Security deposit','operator_terms'=>'Operator terms','maintenance_responsibility'=>'Maintenance','insurance_requirements'=>'Insurance','notes'=>'Notes'] as $key=>$label):?><dt><?= e($label) ?></dt><dd><?= e((string)($terms[$key]??'—')) ?></dd><?php endforeach;?></dl><h3>Technical response</h3><dl><?php foreach($technical as $key=>$value):?><dt><?= e($key) ?></dt><dd><?= e((string)$value) ?></dd><?php endforeach;?></dl><h3>Declared deviations</h3><?php if($deviations):?><dl><?php foreach($deviations as $key=>$value):?><dt><?= e($key) ?></dt><dd><?= e((string)$value) ?></dd><?php endforeach;?></dl><?php else:?><p>No deviations declared.</p><?php endif;?><h3>Documents</h3><?php foreach($documents as $document):?><p><a href="request-offer-document?id=<?= e($document['id']) ?>"><?= e($document['file_name']) ?></a> · version <?= (int)$document['version_number'] ?></p><?php endforeach;?></section>
<?php if($offer['requester_organization_id']===$user['owner_id']&&in_array($offer['status'],['SUBMITTED','VIEWED'],true)):?><section class="transaction-panel"><h2>Requester decision</h2><p>Acceptance is a human commercial commitment. It creates an award and hands the frozen offer into the existing transaction workspace.</p><div class="agreement-actions"><?php $types=$offer['intent']==='EITHER'?['LEASE','PURCHASE']:[$offer['intent']];foreach($types as $type):?><form action="request-action" method="post" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="offer.award"><input type="hidden" name="id" value="<?= e($id) ?>"><input type="hidden" name="transaction_type" value="<?= e($type) ?>"><button class="market-button">Accept for <?= e(strtolower($type)) ?></button></form><?php endforeach;?><form action="request-action" method="post" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="offer.not-select"><input type="hidden" name="id" value="<?= e($id) ?>"><button>Not select</button></form></div></section><?php endif;?>
<?php if($offer['supplier_organization_id']===$user['owner_id']&&in_array($offer['status'],['SUBMITTED','VIEWED'],true)):?><section class="transaction-panel"><details><summary>Submit revised commercial terms</summary><form action="request-action" method="post" enctype="multipart/form-data" class="request-form"><?= csrf_field() ?><input type="hidden" name="action" value="offer.revise"><input type="hidden" name="id" value="<?= e($id) ?>"><label>Price / rate<input type="number" step="0.01" min="0.01" name="amount" value="<?= e((string)($terms['amount']??'')) ?>" required></label><label>Currency<input name="currency" value="<?= e($terms['currency']??'NGN') ?>" required></label><label>Pricing basis<select name="pricing_basis"><?php foreach(['HOURLY','DAILY','WEEKLY','MONTHLY','PROJECT','FIXED'] as $basis):?><option <?= ($terms['pricing_basis']??'')===$basis?'selected':'' ?>><?= $basis ?></option><?php endforeach;?></select></label><label>Available from<input type="date" name="available_from" value="<?= e($terms['available_from']??'') ?>" required></label><label>Available until<input type="date" name="available_until" value="<?= e($terms['available_until']??'') ?>"></label><label>Valid until<input type="datetime-local" name="validity_until" required></label><label>Security deposit<input type="number" step="0.01" name="security_deposit" value="<?= e((string)($terms['security_deposit']??0)) ?>"></label><label class="full">Mobilization / delivery<textarea name="mobilization_delivery"><?= e($terms['mobilization_delivery']??'') ?></textarea></label><label class="full">Demobilization<textarea name="demobilization"><?= e($terms['demobilization']??'') ?></textarea></label><label>Operator terms<textarea name="operator_terms"><?= e($terms['operator_terms']??'') ?></textarea></label><label>Maintenance<textarea name="maintenance_responsibility"><?= e($terms['maintenance_responsibility']??'') ?></textarea></label><label>Insurance<textarea name="insurance_requirements"><?= e($terms['insurance_requirements']??'') ?></textarea></label><label>Technical response<textarea name="technical_response"><?php foreach($technical as $key=>$value)echo e($key.': '.$value)."\n";?></textarea></label><label class="full">Deviations<textarea name="deviations"><?php foreach($deviations as $key=>$value)echo e($key.': '.$value)."\n";?></textarea></label><label class="full">Notes<textarea name="notes"><?= e($terms['notes']??'') ?></textarea></label><label>Supporting document<input type="file" name="supporting_document"></label><button>Submit revision</button></form></details><form action="request-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="offer.withdraw"><input type="hidden" name="id" value="<?= e($id) ?>"><button>Withdraw offer</button></form></section><?php elseif($offer['status']==='DRAFT'&&$offer['supplier_organization_id']===$user['owner_id']):?><section class="transaction-panel"><form action="request-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="offer.submit"><input type="hidden" name="id" value="<?= e($id) ?>"><button class="market-button">Submit draft offer</button></form></section><?php endif;?>
<section class="transaction-panel"><h2>Clarifications</h2><?php foreach($messages as $message):?><article><strong><?= e($message['full_name'].' · '.$message['organization_name']) ?></strong><p><?= nl2br(e($message['message_text'])) ?></p><small><?= e($message['created_at']) ?></small></article><?php endforeach;?><form action="request-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="offer.message"><input type="hidden" name="id" value="<?= e($id) ?>"><textarea name="message" required placeholder="Ask or answer a clarification"></textarea><button>Send message</button></form></section><section class="transaction-panel"><h2>Immutable versions</h2><?php foreach($versions as $version):?><p><strong>Version <?= (int)$version['version_number'] ?></strong> · <?= e($version['created_at']) ?> · valid until <?= e($version['validity_until']) ?></p><?php endforeach;?></section>
